<?php require_once __DIR__.'/../../config/app.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('/pages/suppliers/index.php');$id=(int)($_POST['id']??0);$types=$_POST['product_types']??[];if(!is_array($types))$types=[];$types=array_values(array_unique(array_filter($types,'is_string')));$d=['supplier_name'=>trim($_POST['supplier_name']??''),'email'=>trim($_POST['email']??''),'phone'=>trim($_POST['phone']??''),'address'=>trim($_POST['address']??''),'product_types'=>json_encode($types,JSON_UNESCAPED_UNICODE),'partnership_date'=>trim($_POST['partnership_date']??'')];$allowed=['Food','Drink','Stationery','Uniform'];$er=[];foreach(['supplier_name','email','phone','address','partnership_date'] as $k)if($d[$k]==='')$er[$k]='Kolom wajib diisi.';if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))$er['email']='Format email tidak valid.';if(strlen($d['phone'])>15)$er['phone']='Telepon maksimal 15 karakter.';if(!$types||array_diff($types,$allowed))$er['product_types']='Pilih minimal satu jenis produk yang tersedia.';if(!validateDateValue($d['partnership_date']))$er['partnership_date']='Tanggal tidak valid.';if($er)failForm($er,$d,'/pages/suppliers/edit.php?id='.($id));try{$pdo->beginTransaction();$stmt=$pdo->prepare('UPDATE suppliers SET supplier_name=?,email=?,phone=?,address=?,product_types=?,partnership_date=? WHERE supplier_id=?');$stmt->execute(array_merge(array_values($d),[$id]));$pdo->commit();$_SESSION['success']='Data berhasil diperbarui.';redirect('/pages/suppliers/index.php');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();if($e->getCode()==='23000')failForm(['form'=>'Data duplikat atau melanggar aturan database.'],$d,'/pages/suppliers/edit.php?id='.($id));throw $e;}